"Hopkinsville","containedInPlace":{"@type":"State","name":"Kentucky"}},{"@type":"City","name":"Pikeville","containedInPlace":{"@type":"State","name":"Kentucky"}},{"@type":"City","name":"Ashland","containedInPlace":{"@type":"State","name":"Kentucky"}}],"knowsAbout":["Insurance appraisal","Appraisal clause","Amount of loss","Property claim estimating","Hail and wind damage","Ice storm damage"],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Clause Representation","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/party-appraiser-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowners Insurance Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/roof-hail-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tornado & Wind Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/tornado-wind-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/water-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/fire-smoke-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Storm & Freeze Damage Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/ice-storm-freeze-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Farm, Barn & Equine Property Appraisal","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/farm-equine-property-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/second-look-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://kentuckyinsuranceappraiser.com/insurance-appraisal/neutral-umpire-services/"}}]},"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://kentuckyinsuranceappraiser.com/#website","url":"https://kentuckyinsuranceappraiser.com/","name":"Kentucky Insurance Appraiser","publisher":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#webpage","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/","name":"Insurance Appraisal Terms | Claim Glossary A–Z","description":"Plain-English glossary of insurance appraisal terms: actual cash value, holdback, umpire, overhead and profit, matching, mine subsidence and more.","inLanguage":"en-US","isPartOf":{"@id":"https://kentuckyinsuranceappraiser.com/#website"},"about":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"publisher":{"@id":"https://kentuckyinsuranceappraiser.com/#business"},"dateModified":"2026-11-12","breadcrumb":{"@id":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#breadcrumb"},"primaryImageOfPage":{"@type":"ImageObject","@id":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#primaryimage","url":"https://kentuckyinsuranceappraiser.com/assets/img/photos/desk-calculator.webp","width":1200,"height":900,"caption":"Laptop, notepad and calculator on a desk"},"mainEntity":{"@id":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://kentuckyinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal terms","item":"https://kentuckyinsuranceappraiser.com/appraisal-terms/"}],"@id":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#breadcrumb"},{"@type":"DefinedTermSet","name":"Insurance appraisal terms","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value","description":"The value of damaged property at the time of loss, usually replacement cost minus depreciation. Many policies pay this first and the rest after repairs.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-0"},{"@type":"DefinedTerm","name":"Actual cash value holdback","description":"The portion of a replacement cost claim, usually recoverable depreciation, that an insurer withholds until repairs or replacement are completed.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-1"},{"@type":"DefinedTerm","name":"Additional living expenses","description":"Extra costs of living elsewhere, such as rent, hotel bills and added mileage, while a covered loss makes your home unlivable. Often called Coverage D or loss of use.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-2"},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of the damage under the policy’s valuation terms. This is what appraisal decides.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-3"},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision that sets the amount of loss, signed by any two of the two appraisers and the umpire.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-4"},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy provision that lets either party demand appraisal when they disagree on the amount of loss and describes how the process works.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-5"},{"@type":"DefinedTerm","name":"Appraisal demand","description":"The written notice one party sends the other to invoke the appraisal clause.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-6"},{"@type":"DefinedTerm","name":"Contents inventory","description":"A room-by-room list of damaged or destroyed personal property with descriptions, ages, quantities and replacement prices.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-7"},{"@type":"DefinedTerm","name":"Coverage A, B, C and D","description":"Common homeowners policy sections: A is the dwelling, B is other structures, C is personal property and D is loss of use or additional living expenses.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-8"},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy that lists the named insured, property address, coverage limits, deductibles and policy period.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-9"},{"@type":"DefinedTerm","name":"Deductible","description":"The part of a covered loss you pay before the insurer pays. It may be a flat dollar amount or a percentage of a coverage limit.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-10"},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value for age, wear and condition that separates actual cash value from replacement cost.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-11"},{"@type":"DefinedTerm","name":"Drip edge","description":"Metal flashing installed along roof edges to direct water into the gutters and away from the fascia. Whether it is required can depend on local code.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-12"},{"@type":"DefinedTerm","name":"Earth movement exclusion","description":"Policy language that excludes damage from earthquakes, landslides, sinkholes, subsidence and similar ground movement unless an endorsement adds coverage.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-13"},{"@type":"DefinedTerm","name":"Holdback","description":"Money the insurer withholds from a payment, most often recoverable depreciation, until a condition such as completed repairs is met.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-14"},{"@type":"DefinedTerm","name":"Ice and water shield","description":"A self-adhering waterproof underlayment applied at eaves, valleys and penetrations to protect against ice dams and wind-driven rain.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-15"},{"@type":"DefinedTerm","name":"Kentucky FAIR Plan","description":"The property insurer of last resort for Kentucky owners who cannot find coverage in the regular market.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-16"},{"@type":"DefinedTerm","name":"Line item","description":"A single priced entry in an estimate, such as a quantity of shingles, a labor task or a fee.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-17"},{"@type":"DefinedTerm","name":"Matching","description":"The question of whether replaced materials must reasonably match undamaged materials, which depends on policy language and the facts.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-18"},{"@type":"DefinedTerm","name":"Mine subsidence","description":"Ground sinking caused by the collapse of underground mine workings, which standard policies usually exclude unless separate coverage applies.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-19"},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping a roof or drying out a wet room. Most policies require it.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-20"},{"@type":"DefinedTerm","name":"Mortgagee clause","description":"The policy provision that protects the lender’s interest, which is why mortgage companies are often named on claim checks.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-21"},{"@type":"DefinedTerm","name":"Named insured","description":"The person or entity listed on the declarations page as the policyholder.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-22"},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs to repair or rebuild to current building codes, usually subject to a separate limit.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-23"},{"@type":"DefinedTerm","name":"Overhead and profit","description":"A contractor’s charge for running the business and earning a margin, commonly added when a job needs a general contractor to coordinate several trades.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-24"},{"@type":"DefinedTerm","name":"Party appraiser","description":"The appraiser each side selects in an appraisal. Most policies require this person to be competent and impartial.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-25"},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible equal to a percentage of a coverage limit, often the dwelling limit, commonly used for wind or hail losses.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-26"},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed that some policies require within a set time after the insurer asks for it.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-27"},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation the insurer will pay back once you complete repairs or replacement under a replacement cost policy.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-28"},{"@type":"DefinedTerm","name":"Replacement cost value","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deducting depreciation.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-29"},{"@type":"DefinedTerm","name":"Reservation of rights","description":"A letter in which the insurer continues handling a claim while saying it may later deny coverage for some or all of it.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-30"},{"@type":"DefinedTerm","name":"Scope of loss","description":"The description of what is damaged and what work is needed to repair it, before pricing is applied.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-31"},{"@type":"DefinedTerm","name":"Square (roofing)","description":"A unit of roof area equal to 100 square feet.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-32"},{"@type":"DefinedTerm","name":"Steep charge","description":"An added labor charge for working on roofs above a certain pitch, where extra safety measures slow the work.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-33"},{"@type":"DefinedTerm","name":"Subrogation","description":"The insurer’s right, after paying a claim, to recover its payment from a third party who caused the loss.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-34"},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy clause that sets how long you have to file a lawsuit against the insurer. Kentucky law limits how short it can be.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-35"},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for damage or costs discovered after the original estimate, often during repairs.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-36"},{"@type":"DefinedTerm","name":"Tear-off","description":"Removing existing roofing layers down to the deck before installing a new roof.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-37"},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral chosen by the appraisers, or appointed by a court, to decide items the appraisers cannot agree on.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-38"},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors that prices line items using regional price lists.","url":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#t-39"}],"@id":"https://kentuckyinsuranceappraiser.com/appraisal-terms/#definedtermset"}]}</script>
</head>
